import { findAndRemoveImports, getAST, parseFrontmatter, stringifyTree } from '@mintlify/common';
import { getMdx } from '@mintlify/common/server-mdx';
import { createPage, preparseMdxTree } from '@mintlify/prebuild';
import fse from 'fs-extra';
import { mkdtemp, readdir, rm } from 'fs/promises';
import { tmpdir } from 'os';
import { join, sep } from 'path';
const testPaths = vi.hoisted(() => ({ cmd: '', public: '' }));
vi.mock('../constants.js', () => ({
    get CMD_EXEC_PATH() {
        return testPaths.cmd;
    },
    get NEXT_PUBLIC_PATH() {
        return testPaths.public;
    },
}));
vi.mock('@mintlify/common', async (importOriginal) => {
    const actual = await importOriginal();
    return { ...actual, getAST: vi.fn(actual.getAST) };
});
vi.mock('../local-preview/listener/utils.js', () => ({
    getCurrentVariables: vi.fn(async () => ({ brand: 'Acme' })),
    handleParseError: vi.fn(),
}));
import { resolvePageImports } from '../local-preview/listener/resolve-page-imports.js';
import { setPackageImportOptions } from '../local-preview/packages/state.js';
import { collectPackageIslands, PackageIslandCollector } from '../packages/collect.js';
import { readPackagesSetup } from '../packages/setup.js';
const CHARTS = `---
title: Charts
---

import { LineChart, Line } from "recharts";
import { RevenueChart } from "/snippets/revenue.jsx";

export const data = [{ v: 1 }, { v: 3 }];

# {{brand}} charts

<LineChart width={400} height={200} data={data}>
  <Line dataKey="v" isAnimationActive={false} />
</LineChart>

<Note>
  <RevenueChart currency="USD" />
</Note>
`;
const BROKEN = `import { LineChart } from "recharts";

Intro.

<LineChart width={400} height={200} onClick={() => {}} />
`;
const UNDECLARED = `import { debounce } from "lodash";

Nothing here.
`;
const REVENUE = `import { BarChart, Bar } from "recharts";
import { formatMoney } from "./format.js";

export const RevenueChart = ({ currency }) => (
  <BarChart width={300} height={150} data={[{ v: 1 }]}>
    <Bar dataKey="v" name={formatMoney(1, currency)} />
  </BarChart>
);
`;
const BAR_SNIPPET = `import { BarChart, Bar } from "recharts";

<BarChart width={300} height={150} data={[{ v: 1 }]}>
  <Bar dataKey="v" name="{{brand}} revenue" />
</BarChart>
`;
const writeDocs = async (root) => {
    await fse.outputJson(join(root, 'docs.json'), {
        name: 'Docs',
        packages: { provider: '/snippets\\provider.jsx' },
        variables: { brand: 'Acme' },
    });
    await fse.outputJson(join(root, 'package.json'), {
        dependencies: { react: '18.3.1', 'react-dom': '18.3.1', recharts: '2.15.4' },
    });
    await fse.outputFile(join(root, 'charts.mdx'), CHARTS);
    await fse.outputFile(join(root, 'guides/broken.mdx'), BROKEN);
    await fse.outputFile(join(root, 'undeclared.mdx'), UNDECLARED);
    await fse.outputFile(join(root, 'plain.mdx'), '# Plain\n');
    await fse.outputFile(join(root, 'snippets/revenue.jsx'), REVENUE);
    await fse.outputFile(join(root, 'snippets/format.js'), 'export const formatMoney = (v) => `$${v}`;\n');
    await fse.outputFile(join(root, 'snippets/provider.jsx'), 'export const Provider = ({ children }) => children;\n');
};
const localSnippets = async () => {
    const dir = join(testPaths.cmd, '_snippets');
    if (!(await fse.pathExists(dir)))
        return [];
    const names = (await readdir(dir, { recursive: true })).filter((name) => name.endsWith('.mdx'));
    return Promise.all(names.map(async (name) => ({
        snippetFileLocation: name.split(sep).join('/'),
        content: await fse.readFile(join(dir, name), 'utf8'),
    })));
};
const compileLikeMintDev = async (filename, packageBuild) => {
    const sourcePath = join(testPaths.cmd, filename);
    let content = await fse.readFile(sourcePath, 'utf8');
    const tree = await preparseMdxTree(content, testPaths.cmd, sourcePath);
    const importsResponse = await findAndRemoveImports(tree);
    content = stringifyTree(await resolvePageImports({ ...importsResponse, filename }));
    const { pageContent } = await createPage(filename, content, testPaths.cmd, [], []);
    return getMdx({
        path: filename.replace(/\.mdx$/, ''),
        content: parseFrontmatter(pageContent).body,
        metadata: {},
        snippets: await localSnippets(),
        subdomain: 'local',
        codeStyling: undefined,
        tailwindSelectors: [],
        variables: { brand: 'Acme' },
        packageBuild,
    });
};
describe('collectPackageIslands', () => {
    let root;
    beforeEach(async () => {
        root = await mkdtemp(join(tmpdir(), 'packages-collect-'));
        testPaths.cmd = join(root, 'docs');
        testPaths.public = join(root, 'public');
        await fse.ensureDir(testPaths.public);
        await writeDocs(testPaths.cmd);
    });
    afterEach(async () => {
        setPackageImportOptions(undefined);
        await rm(root, { recursive: true, force: true });
    });
    it('reads the packages setup and normalizes the provider path', async () => {
        const setup = await readPackagesSetup(testPaths.cmd);
        expect(setup?.packages.provider).toBe('/snippets/provider.jsx');
        expect(setup?.packageNames).toEqual(new Set(['react', 'react-dom', 'recharts']));
        expect(setup?.variables).toEqual({ brand: 'Acme' });
        expect(setup?.errors).toEqual([]);
    });
    it('returns undefined without a packages key', async () => {
        await fse.outputJson(join(testPaths.cmd, 'docs.json'), { name: 'Docs' });
        expect(await readPackagesSetup(testPaths.cmd)).toBeUndefined();
    });
    it('returns undefined without a docs.json and rejects one that does not parse', async () => {
        await fse.outputFile(join(testPaths.cmd, 'docs.json'), '{ "packages": {}, }');
        await expect(readPackagesSetup(testPaths.cmd)).rejects.toThrow(/^docs\.json could not be loaded: \S/);
        await fse.outputJson(join(testPaths.cmd, 'docs.json'), ['packages']);
        await expect(readPackagesSetup(testPaths.cmd)).rejects.toThrow('docs.json is not a JSON object');
        await fse.remove(join(testPaths.cmd, 'docs.json'));
        expect(await readPackagesSetup(testPaths.cmd)).toBeUndefined();
    });
    it('parses only the pages that can hold package components', async () => {
        vi.mocked(getAST).mockClear();
        const collected = await collectPackageIslands({
            docsRoot: testPaths.cmd,
            packageNames: new Set(['recharts']),
            variables: { brand: 'Acme' },
        });
        expect(collected.pages['plain.mdx']).toEqual({ ids: [], errors: [] });
        const parsed = vi.mocked(getAST).mock.calls.map(([, file]) => file);
        expect(parsed).toContain('/charts.mdx');
        expect(parsed).not.toContain('/plain.mdx');
    });
    it('collects inline and snippet islands, errors and warnings across pages', async () => {
        const setup = await readPackagesSetup(testPaths.cmd);
        const collected = await collectPackageIslands({
            docsRoot: testPaths.cmd,
            packageNames: setup?.packageNames ?? new Set(),
            variables: setup?.variables,
            provider: setup?.packages.provider,
        });
        expect(collected.packageSnippets).toEqual(new Set(['/snippets/revenue.jsx']));
        expect(Object.keys(collected.snippetFiles).sort()).toEqual([
            '/snippets/provider.jsx',
            '/snippets/revenue.jsx',
        ]);
        expect(collected.snippetFiles['/snippets/revenue.jsx']).toBe(REVENUE);
        expect(collected.islands.map((island) => island.kind)).toEqual(['inline', 'snippet']);
        expect(collected.pages['charts.mdx']?.ids).toEqual(collected.islands.map((i) => i.id));
        expect(collected.pages['plain.mdx']?.ids).toEqual([]);
        expect(collected.errors).toEqual([
            expect.objectContaining({ file: 'guides/broken.mdx', line: 5 }),
            {
                file: 'undeclared.mdx',
                line: 1,
                message: `imports "lodash", which isn't listed in package.json dependencies.`,
            },
        ]);
        expect(collected.warnings).toEqual([
            expect.objectContaining({
                file: 'undeclared.mdx',
                message: expect.stringContaining('lodash'),
            }),
        ]);
    });
    it('resolves relatively imported snippets before the snippets that import them', async () => {
        await fse.outputFile(join(testPaths.cmd, 'snippets/a-outer.mdx'), 'import Inner from "./b-inner.mdx";\n\n<Inner />\n');
        await fse.outputFile(join(testPaths.cmd, 'snippets/b-inner.mdx'), 'import { RevenueChart } from "./revenue.jsx";\n\n<RevenueChart currency="EUR" />\n');
        await fse.outputFile(join(testPaths.cmd, 'nested.mdx'), 'import Outer from "/snippets/a-outer.mdx";\n\n<Outer />\n');
        const setup = await readPackagesSetup(testPaths.cmd);
        const collected = await collectPackageIslands({
            docsRoot: testPaths.cmd,
            packageNames: setup?.packageNames ?? new Set(),
            variables: setup?.variables,
        });
        const [id] = collected.pages['nested.mdx']?.ids ?? [];
        expect(collected.islands.find((island) => island.id === id)?.kind).toBe('snippet');
        expect(collected.warnings).not.toContainEqual(expect.objectContaining({ file: 'snippets/a-outer.mdx' }));
    });
    it('produces the island ids that mint dev compiles for the page', async () => {
        const setup = await readPackagesSetup(testPaths.cmd);
        const collected = await collectPackageIslands({
            docsRoot: testPaths.cmd,
            packageNames: setup?.packageNames ?? new Set(),
            variables: setup?.variables,
        });
        setPackageImportOptions({
            packageNames: setup?.packageNames ?? new Set(),
            packageSnippets: collected.packageSnippets,
        });
        const islands = Object.fromEntries(collected.islands.map((island) => [
            island.id,
            { prefix: `mi-${island.id}-`, html: '<svg></svg>' },
        ]));
        const compiled = await compileLikeMintDev('charts.mdx', {
            buildId: 'abc',
            islands,
            packageNames: [...(setup?.packageNames ?? [])],
            packageSnippets: [...collected.packageSnippets],
        });
        expect(Object.keys(compiled.mdxExtracts.islands ?? {})).toEqual(collected.pages['charts.mdx']?.ids);
        expect(compiled.mdxExtracts.packageBaseUrl).toBe('/_mintlify/pkg/abc');
        expect(compiled.mdxSource.compiledSource).not.toMatch(/LineChart|RevenueChart/);
    });
    it('reports a <Snippet file> that uses package components instead of extracting it', async () => {
        await fse.outputFile(join(testPaths.cmd, '_snippets/bar.mdx'), BAR_SNIPPET);
        await fse.outputFile(join(testPaths.cmd, 'revenue.mdx'), '# Revenue\n\n<Snippet file="bar.mdx" />\n');
        const setup = await readPackagesSetup(testPaths.cmd);
        const collected = await collectPackageIslands({
            docsRoot: testPaths.cmd,
            packageNames: setup?.packageNames ?? new Set(),
            variables: setup?.variables,
        });
        expect(collected.pages['revenue.mdx']).toEqual({ ids: [], errors: [] });
        expect(collected.errors).toContainEqual({
            file: '_snippets/bar.mdx',
            message: expect.stringContaining('<Snippet>'),
        });
    });
    it('falls back to the snippet trees of a collector for the same docs root only', async () => {
        const setup = await readPackagesSetup(testPaths.cmd);
        const input = { packageNames: setup?.packageNames ?? new Set() };
        const previous = new PackageIslandCollector({ ...input, docsRoot: testPaths.cmd });
        expect((await previous.collectAll()).packageSnippets).toContain('/snippets/revenue.jsx');
        const otherRoot = join(root, 'other');
        await fse.copy(testPaths.cmd, otherRoot);
        for (const docsRoot of [testPaths.cmd, otherRoot]) {
            await fse.outputFile(join(docsRoot, 'snippets/revenue.jsx'), REVENUE.replace('</BarChart>', ''));
        }
        const same = new PackageIslandCollector({ ...input, docsRoot: testPaths.cmd });
        same.inheritSnippetTrees(previous);
        const other = new PackageIslandCollector({ ...input, docsRoot: otherRoot });
        other.inheritSnippetTrees(previous);
        expect((await same.collectAll()).packageSnippets).toContain('/snippets/revenue.jsx');
        expect((await other.collectAll()).packageSnippets).not.toContain('/snippets/revenue.jsx');
    });
    it('inherits snippet trees once the previous collector finishes its queued updates', async () => {
        const setup = await readPackagesSetup(testPaths.cmd);
        const input = { docsRoot: testPaths.cmd, packageNames: setup?.packageNames ?? new Set() };
        const revenue = join(testPaths.cmd, 'snippets/revenue.jsx');
        const previous = new PackageIslandCollector(input);
        expect((await previous.collectAll()).packageSnippets).toContain('/snippets/revenue.jsx');
        await fse.remove(revenue);
        const deleted = previous.collectAll();
        const next = new PackageIslandCollector(input);
        next.inheritSnippetTrees(previous);
        expect((await deleted).packageSnippets).not.toContain('/snippets/revenue.jsx');
        await fse.outputFile(revenue, REVENUE.replace('</BarChart>', ''));
        expect((await next.collectAll()).packageSnippets).not.toContain('/snippets/revenue.jsx');
    });
    it('updates one page without re-reading the rest', async () => {
        const setup = await readPackagesSetup(testPaths.cmd);
        const collector = new PackageIslandCollector({
            docsRoot: testPaths.cmd,
            packageNames: setup?.packageNames ?? new Set(),
        });
        const before = await collector.collectAll();
        await fse.outputFile(join(testPaths.cmd, 'charts.mdx'), CHARTS.replace('<Line dataKey="v"', '<Line dataKey="v" strokeWidth={3}'));
        await fse.outputFile(join(testPaths.cmd, 'plain.mdx'), BROKEN);
        const after = await collector.updatePage('charts.mdx');
        expect(after.pages['charts.mdx']?.ids[0]).not.toBe(before.pages['charts.mdx']?.ids[0]);
        expect(after.pages['charts.mdx']?.ids[1]).toBe(before.pages['charts.mdx']?.ids[1]);
        expect(after.pages['plain.mdx']?.ids).toEqual([]);
        expect(after.islands).toHaveLength(2);
        await fse.remove(join(testPaths.cmd, 'charts.mdx'));
        expect((await collector.updatePage('charts.mdx')).islands).toEqual([]);
    });
});
